import { t } from "@shared/i18n";
import { approximateSite, cosmeticCss, cosmeticSelectors, hostMatches, sanitizeCosmeticIndex, type CosmeticIndex } from "@shared/blocklist";
import { COOKIE_BANNER_RULES, DEFAULT_AGENT_OPTIONS, bannerHandled, sanitizeBannerResult, type BannerResult } from "@shared/cookie-banners";
import type { PrivacyEvent } from "@shared/privacy-stats";
import type { BlockedEvent } from "../../modules/content-blocker";
// Generated by scripts/build-blocklists.mjs (postinstall), never committed.
import bundledCosmetic from "../generated/cosmetic.json";
import agentSource from "../generated/cookie-banner-agent.json";

/**
 * The phone's shield (ADR-051): what runs in the page, on both platforms and in Expo Go too —
 * element hiding from EasyList (a style sheet injected at document start and after the load) and
 * the cookie banner agent of ADR-046 (nonce per document, result validated) — plus the per-site
 * switch ("Bouclier") and the counters. Network blocking is native (`modules/content-blocker`).
 */

export const SHIELD_UNAVAILABLE_NOTE = (): string => t("mobile.shields.fullBlockerAvailableCompiled");

/** The shield's site key of a host: its registrable domain (approximated, like the native side). */
export const shieldSiteOf = (host: string | null | undefined): string | null => (host ? approximateSite(host.toLowerCase()) : null);

/** Whether the shield is off on pages of `host` (the list holds sites). */
export const shieldOffFor = (host: string | null | undefined, sitesOff: readonly string[]): boolean =>
  !!host && sitesOff.some((site) => hostMatches(host.toLowerCase(), site));

/** The list with `site` added (shield off) or removed (shield on). */
export function toggleShieldSite(sitesOff: readonly string[], site: string, off: boolean): string[] {
  const rest = sitesOff.filter((entry) => entry !== site);
  return off ? [...rest, site].sort() : rest;
}

// --- Element hiding ---------------------------------------------------------------------------

let index: CosmeticIndex | null = null;
const cssCache = new Map<string, string>();

/** The element hiding style sheet of a host ("" when there is nothing to hide). */
export function cosmeticCssFor(host: string, source: unknown = bundledCosmetic): string {
  if (source !== bundledCosmetic) return cosmeticCss(cosmeticSelectors(sanitizeCosmeticIndex(source), host));
  index ??= sanitizeCosmeticIndex(bundledCosmetic);
  let css = cssCache.get(host);
  if (css === undefined) {
    css = cosmeticCss(cosmeticSelectors(index, host));
    if (cssCache.size >= 16) cssCache.delete(cssCache.keys().next().value!);
    cssCache.set(host, css);
  }
  return css;
}

/** Injected in the page: puts (or updates) the hiding style sheet. Idempotent. */
export function cosmeticScript(css: string): string {
  return `(function(css){var id="__browser_shield_css";var el=document.getElementById(id);
if(!el){el=document.createElement("style");el.id=id;(document.head||document.documentElement).appendChild(el);}
if(el.textContent!==css)el.textContent=css;})(${JSON.stringify(css)});true;`;
}

// --- Cookie banners (ADR-046) -----------------------------------------------------------------

export const COOKIE_BANNER_MESSAGE = "cookie-banner";

/**
 * The agent's DOM port in the page (the desktop runs it in an isolated world; a WebView has none,
 * so here it shares the page's world: the page could see or fake it, which only affects a counter).
 * Hiding is a style sheet the port appends (the desktop's main process uses `insertCSS`).
 */
const PAGE_PORT = `{
query:function(list){var found=[];list.split(",").forEach(function(selector){selector=selector.trim();if(!selector)return;
try{var parts=selector.split(">>>").map(function(p){return p.trim();});
if(parts.length===1){found.push.apply(found,[].slice.call(document.querySelectorAll(selector)));return;}
[].slice.call(document.querySelectorAll(parts[0])).forEach(function(host){if(host.shadowRoot)found.push.apply(found,[].slice.call(host.shadowRoot.querySelectorAll(parts[1])));});}catch(e){}});return found;},
visible:function(el){if(!el.isConnected||!el.getClientRects().length)return false;var s=getComputedStyle(el);return s.visibility!=="hidden"&&s.display!=="none";},
label:function(el){return String(el.innerText||el.textContent||el.getAttribute("aria-label")||el.getAttribute("title")||el.value||"").trim().slice(0,200);},
click:function(el){el.click();},
hide:function(selectors,unlock){var plain=selectors.filter(function(s){return s.indexOf(">>>")<0;});var css="";
if(plain.length)css+=plain.join(",")+"{display:none!important}";if(unlock.length)css+=unlock.join(",")+"{overflow:auto!important}";
if(!css)return;var st=document.createElement("style");st.textContent=css;(document.head||document.documentElement).appendChild(st);},
changed:function(ms){return new Promise(function(resolve){var start=Date.now(),done=false,timer;
function finish(){if(done)return;done=true;observer.disconnect();clearTimeout(timer);resolve();}
var observer=new MutationObserver(function(){setTimeout(finish,Math.max(0,100-(Date.now()-start)));});
observer.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:["class","style","hidden","open"]});
timer=setTimeout(finish,ms);});},
now:function(){return Date.now();}
}`;

/** Injected after the load of a main-frame document: runs the agent once, posts its result with the nonce. */
export function cookieBannerScript(nonce: string, source: string = agentSource.source): string | null {
  if (!source) return null;
  return `(function(nonce){if(window.__browserCookieBanners)return;window.__browserCookieBanners=true;
var post=window.ReactNativeWebView&&window.ReactNativeWebView.postMessage.bind(window.ReactNativeWebView);if(!post)return;
var agent=(${source});
agent(${JSON.stringify(COOKIE_BANNER_RULES)},${PAGE_PORT},${JSON.stringify(DEFAULT_AGENT_OPTIONS)}).then(function(result){
if(result&&result.outcome!=="none")post(JSON.stringify({type:${JSON.stringify(COOKIE_BANNER_MESSAGE)},nonce:nonce,result:result}));},function(){});
})(${JSON.stringify(nonce)});true;`;
}

const originOf = (url: string): string | null => {
  try {
    const parsed = new URL(url);
    return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.origin : null;
  } catch {
    return null;
  }
};


/** Which cookie banner messages a tab accepts: this document's nonce, same origin, once. */
export class CookieBannerGuard {
  private nonce: string | null = null;
  private origin: string | null = null;

  constructor(private readonly newNonce: () => string) {}

  loadStarted(): void {
    this.nonce = null;
    this.origin = null;
  }

  /** The script for the document that just loaded, or null (not a web page, or already running). */
  loadEnded(url: string): string | null {
    const origin = originOf(url);
    if (!origin || (this.nonce && this.origin === origin)) return null;
    this.origin = origin;
    this.nonce = this.newNonce();
    return cookieBannerScript(this.nonce);
  }

  /** The validated result of one of our messages; undefined when the message is not ours. */
  parse(data: unknown, messageUrl: string, pageUrl: string): BannerResult | null | undefined {
    if (!this.nonce || !this.origin || typeof data !== "string" || data.length > 512) return undefined;
    if (originOf(messageUrl) !== this.origin || originOf(pageUrl) !== this.origin) return undefined;
    let message: { type?: unknown; nonce?: unknown; result?: unknown };
    try {
      message = JSON.parse(data);
    } catch {
      return undefined;
    }
    if (message?.type !== COOKIE_BANNER_MESSAGE || message.nonce !== this.nonce) return undefined;
    this.nonce = null; // One result per document.
    return sanitizeBannerResult(message.result);
  }
}

// --- Counters ---------------------------------------------------------------------------------

/** Privacy events of native blocked-request batches; pages of private tabs (`privateHosts`) are not counted. */
export function blockedEvents(events: readonly BlockedEvent[], privateHosts: ReadonlySet<string>): PrivacyEvent[] {
  const out: PrivacyEvent[] = [];
  for (const event of events) {
    if (typeof event?.page !== "string" || typeof event.tracker !== "string" || !Number.isFinite(event.count) || event.count < 1) continue;
    if (privateHosts.has(event.page)) continue;
    out.push({ counter: "trackers", site: shieldSiteOf(event.page) ?? "", tracker: shieldSiteOf(event.tracker) ?? undefined, count: Math.min(10_000, Math.floor(event.count)) });
  }
  return out;
}

/** The privacy event of a cookie banner dealt with on a page, or null. */
export function bannerEvent(host: string | null, result: BannerResult | null): PrivacyEvent | null {
  return bannerHandled(result) ? { counter: "cookieBanners", site: shieldSiteOf(host) ?? "" } : null;
}

// --- Per tab ----------------------------------------------------------------------------------

/** What the shield does in a kind of tab (one stable object per settings change). */
export interface TabShield {
  /** Ads and trackers blocked (element hiding here, requests natively). */
  blocker: boolean;
  /** Sites where the shield is off: nothing at all runs there. */
  sitesOff: readonly string[];
  /** Cookie banners refused (shared setting `privacy.cookieBanners`). */
  cookieBanners: boolean;
  /** Sites whose banners are left alone (`privacy.cookieBannerExceptions`). */
  bannerExceptions: readonly string[];
}

/** The element hiding style sheet for a page of `host` ("" when none, or the shield is off there). */
export function shieldCss(shield: TabShield | undefined, host: string | null): string {
  if (!shield?.blocker || !host || shieldOffFor(host, shield.sitesOff)) return "";
  return cosmeticCssFor(host);
}

/** Whether the cookie banner agent runs on a page of `host`. */
export function shieldBanners(shield: TabShield | undefined, host: string | null): boolean {
  return !!shield?.cookieBanners && !!host && !shieldOffFor(host, shield.sitesOff) && !shieldOffFor(host, shield.bannerExceptions);
}
